def grad(p):
    # the narrow valley L = 0.05*x**2 + 2*y**2 from the video
    x, y = p
    return [0.1 * x, 4.0 * y]

def momentum(grad, p0, lr, beta, steps):
    p = list(p0)
    v = [0.0] * len(p)
    for _ in range(steps):
        g = grad(p)
        for i in range(len(p)):
            v[i] = beta * v[i] + g[i]
            p[i] = p[i] - lr * v[i]
    return p
